-- Generated by dag_tools.systemlink.sql from the rule table in
-- dag_tools.systemlink.measurements. Do not edit by hand: a test
-- compares the generator's output against this file byte for byte.
-- Fails under the contract rule `duplicate_key`, which this model's
-- contract document declares. The id is in this comment and is
-- selected as a column, so a failure names the rule wherever
-- it is read: a failure naming an id outside the contract's
-- `rules:` cannot be acted on by anyone reading the contract.

with duplicated as (
    select
        part_number,
        program_name,
        step_path,
        parameter_name,
        units,
        count(*) as n_rows
    from {{ ref('test_catalog') }}
    group by
        part_number,
        program_name,
        step_path,
        parameter_name,
        units
    having count(*) > 1
)

select
    'duplicate_key' as rule_id,
    duplicated.*
from duplicated
